from math import sqrt
from numbers import Real


def most_correlated_columns(data):
    if not data or len(data) < 2:
        raise ValueError("At least two columns are required")

    names = list(data)
    columns = [data[name] for name in names]
    n = len(columns[0])

    if n < 2:
        raise ValueError("At least two data points are required")

    for column in columns:
        if len(column) != n:
            raise ValueError("All columns must have the same length")
        for value in column:
            if not isinstance(value, Real):
                raise TypeError("All column values must be numeric")

    def pearson(x, y):
        mean_x = sum(x) / n
        mean_y = sum(y) / n

        numerator = 0.0
        sum_sq_x = 0.0
        sum_sq_y = 0.0

        for a, b in zip(x, y):
            dx = a - mean_x
            dy = b - mean_y
            numerator += dx * dy
            sum_sq_x += dx * dx
            sum_sq_y += dy * dy

        denominator = sqrt(sum_sq_x * sum_sq_y)
        if denominator == 0:
            return 0.0

        return numerator / denominator

    best_pair = None
    best_corr = -1.0

    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            corr = abs(pearson(data[names[i]], data[names[j]]))
            if corr > best_corr:
                best_corr = corr
                best_pair = (names[i], names[j])

    return best_pair
