def kmeans_centers(points, n_clusters):
    if points is None or len(points) == 0:
        raise ValueError("points must contain at least one point")
    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")
    if n_clusters > len(points):
        raise ValueError("n_clusters cannot exceed the number of points")

    pts = [(float(x), float(y)) for x, y in points]
    pts.sort()
    n = len(pts)
    k = int(n_clusters)

    if k == 1:
        return [[sum(x for x, _ in pts) / n, sum(y for _, y in pts) / n]]

    if k == n:
        return [[x, y] for x, y in pts]

    # Deterministic farthest-first initialization.
    centers = [pts[0]]
    used = {0}

    for _ in range(1, k):
        best_i = None
        best_d = -1.0

        for i, p in enumerate(pts):
            if i in used:
                continue

            d = min(
                (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2
                for c in centers
            )

            if (
                best_i is None
                or d > best_d + 1e-15
                or (
                    abs(d - best_d) <= 1e-15
                    and p < pts[best_i]
                )
            ):
                best_i = i
                best_d = d

        centers.append(pts[best_i])
        used.add(best_i)

    # Lloyd's algorithm.
    for _ in range(100):
        clusters = [[] for _ in range(k)]

        for p in pts:
            best_j = 0
            best_d = (p[0] - centers[0][0]) ** 2 + (p[1] - centers[0][1]) ** 2

            for j in range(1, k):
                d = (p[0] - centers[j][0]) ** 2 + (p[1] - centers[j][1]) ** 2
                if d < best_d - 1e-15:
                    best_d = d
                    best_j = j

            clusters[best_j].append(p)

        # Handle empty clusters by moving the worst-fit point from a larger cluster.
        for j in range(k):
            if clusters[j]:
                continue

            move_from = None
            move_point = None
            worst_d = -1.0

            for ci, cl in enumerate(clusters):
                if len(cl) <= 1:
                    continue

                cx, cy = centers[ci]

                for p in cl:
                    d = (p[0] - cx) ** 2 + (p[1] - cy) ** 2

                    if (
                        move_point is None
                        or d > worst_d + 1e-15
                        or (
                            abs(d - worst_d) <= 1e-15
                            and p < move_point
                        )
                    ):
                        worst_d = d
                        move_point = p
                        move_from = ci

            if move_point is not None:
                clusters[move_from].remove(move_point)
                clusters[j].append(move_point)

        new_centers = []

        for j in range(k):
            if clusters[j]:
                count = len(clusters[j])
                cx = sum(p[0] for p in clusters[j]) / count
                cy = sum(p[1] for p in clusters[j]) / count
                new_centers.append((cx, cy))
            else:
                new_centers.append(centers[j])

        shift = max(
            (new_centers[j][0] - centers[j][0]) ** 2
            + (new_centers[j][1] - centers[j][1]) ** 2
            for j in range(k)
        )

        centers = new_centers

        if shift < 1e-20:
            break

    result = [[float(x), float(y)] for x, y in centers]
    result.sort(key=lambda p: (p[0], p[1]))
    return result
