import re
from collections import Counter
from math import sqrt


def text_similarity_scores(text1, text2):
    def clean(text):
        return re.sub(r'[\W_]+', ' ', text.lower())

    s1 = clean(text1)
    s2 = clean(text2)

    words1 = s1.split()
    words2 = s2.split()

    if not words1 or not words2:
        cosine = 0.0
    else:
        c1 = Counter(words1)
        c2 = Counter(words2)

        dot = sum(c1[word] * c2.get(word, 0) for word in c1)
        norm1 = sqrt(sum(count * count for count in c1.values()))
        norm2 = sqrt(sum(count * count for count in c2.values()))

        cosine = dot / (norm1 * norm2)

    a, b = s1, s2
    if len(a) < len(b):
        a, b = b, a

    prev = [0] * (len(b) + 1)

    for ch in a:
        curr = [0] * (len(b) + 1)
        for j, other in enumerate(b, start=1):
            if ch == other:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr

    lcs_len = prev[-1]
    total_len = len(s1) + len(s2)

    if total_len == 0:
        ratio = 1.0
    else:
        ratio = 2.0 * lcs_len / total_len

    return cosine, ratio
