import csv
import io
import re

_NUMBER_RE = re.compile(
    r'^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$'
)

def _convert_cell(value):
    if value is None or value == "":
        return None

    stripped = value.strip()
    if stripped and _NUMBER_RE.fullmatch(stripped):
        if any(ch in stripped for ch in ".eE"):
            return float(stripped)
        return int(stripped)

    return value


def merge_csv_texts(csv_texts):
    if not csv_texts:
        return []

    parsed_tables = []
    all_columns = []
    seen_columns = set()

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text, newline=""))

        try:
            header = next(reader)
        except StopIteration:
            continue

        for column in header:
            if column not in seen_columns:
                seen_columns.add(column)
                all_columns.append(column)

        rows = []
        for row in reader:
            if row == []:  # skip blank lines
                continue
            rows.append(row)

        parsed_tables.append((header, rows))

    result = []

    for header, rows in parsed_tables:
        for row in rows:
            record = {column: None for column in all_columns}

            for index, column in enumerate(header):
                if index < len(row):
                    record[column] = _convert_cell(row[index])
                else:
                    record[column] = None

            result.append(record)

    return result
