from collections import Counter
from math import sqrt


def letter_count_correlations(strings):
    if not strings:
        return None

    counters = [Counter(s) for s in strings]
    letters = sorted({letter for counter in counters for letter in counter})

    n = len(strings)

    # Counts for each letter across all strings
    counts = {
        letter: [counter[letter] for counter in counters]
        for letter in letters
    }

    # Precompute means and centered-value magnitudes
    means = {}
    stds = {}

    for letter in letters:
        values = counts[letter]
        mean = sum(values) / n
        means[letter] = mean
        stds[letter] = sqrt(sum((value - mean) ** 2 for value in values))

    result = {}

    for x in letters:
        result[x] = {}
        for y in letters:
            x_values = counts[x]
            y_values = counts[y]

            numerator = sum(
                (x_values[i] - means[x]) * (y_values[i] - means[y])
                for i in range(n)
            )

            denominator = stds[x] * stds[y]
            result[x][y] = numerator / denominator

    return result
