import csv
import io

def normalize_numeric_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV has no header")

    rows = [row for row in reader if row]

    columns = {name: [] for name in header}
    for row in rows:
        for i, name in enumerate(header):
            columns[name].append(row[i] if i < len(row) else "")

    def is_numeric(value):
        if value.strip() == "":
            return False
        try:
            float(value)
            return True
        except ValueError:
            return False

    numeric_columns = {
        name for name, values in columns.items()
        if values and all(is_numeric(v) for v in values)
    }

    if not numeric_columns:
        raise ValueError("No numeric columns found")

    result = {}
    for name in header:
        values = columns[name]
        if name in numeric_columns:
            numbers = [float(v) for v in values]
            minimum = min(numbers)
            maximum = max(numbers)

            if maximum == minimum:
                result[name] = [0.0 for _ in numbers]
            else:
                result[name] = [
                    (value - minimum) / (maximum - minimum)
                    for value in numbers
                ]
        else:
            result[name] = values

    return result
