def five_column_correlation_matrix(array):
    if not array:
        raise ValueError("input must not be empty")

    n = len(array)
    for row in array:
        if len(row) != 5:
            raise ValueError("each row must have exactly 5 values")

    means = [sum(row[j] for row in array) / n for j in range(5)]
    centered = [
        [row[j] - means[j] for row in array]
        for j in range(5)
    ]
    sum_squares = [
        sum(x * x for x in centered[j])
        for j in range(5)
    ]

    result = [[0.0 for _ in range(5)] for _ in range(5)]

    for i in range(5):
        for j in range(5):
            if i == j:
                result[i][j] = 1.0
            elif sum_squares[i] == 0.0 or sum_squares[j] == 0.0:
                result[i][j] = 0.0
            else:
                covariance = sum(
                    centered[i][k] * centered[j][k]
                    for k in range(n)
                )
                denominator = (sum_squares[i] * sum_squares[j]) ** 0.5
                correlation = covariance / denominator

                if abs(correlation) < 1e-15:
                    correlation = 0.0
                elif abs(correlation - 1.0) < 1e-15:
                    correlation = 1.0
                elif abs(correlation + 1.0) < 1e-15:
                    correlation = -1.0

                result[i][j] = float(correlation)

    return result
