from html.parser import HTMLParser

_VOID_ELEMENTS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr"
}

class _FirstTagTextParser(HTMLParser):
    def __init__(self, tag):
        super().__init__(convert_charrefs=True)
        self.target = tag.lower()
        self.found = False
        self.active = False
        self.done = False
        self.stack = []
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        tag = tag.lower()

        if self.active:
            if tag not in _VOID_ELEMENTS:
                self.stack.append(tag)
        elif not self.found and tag == self.target:
            self.found = True
            if tag in _VOID_ELEMENTS:
                self.done = True
            else:
                self.active = True
                self.stack = []
                self.parts = []

    def handle_endtag(self, tag):
        if self.done or not self.active:
            return

        tag = tag.lower()

        if self.stack:
            if self.stack[-1] == tag:
                self.stack.pop()
            elif tag in self.stack:
                while self.stack and self.stack[-1] != tag:
                    self.stack.pop()
                if self.stack:
                    self.stack.pop()
            elif tag == self.target:
                self.active = False
                self.done = True
        elif tag == self.target:
            self.active = False
            self.done = True

    def handle_data(self, data):
        if self.active and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()

    if not parser.found:
        return None

    text = "".join(parser.parts)
    return text if text != "" else None
