import csv
import io
import math


def predict_linear_regression(train_csv, test_csv, target):
    def parse_value(cell):
        if cell is None:
            raise ValueError("missing value")
        s = cell.strip()
        if s == "":
            raise ValueError("missing value")
        try:
            value = float(s)
        except ValueError:
            raise ValueError("non-numeric value")
        if not math.isfinite(value):
            raise ValueError("non-finite value")
        return value

    def read_csv(text):
        rows = list(csv.reader(io.StringIO(text)))
        if not rows:
            raise ValueError("empty CSV")
        header = rows[0]
        if header and header[0].startswith("\ufeff"):
            header[0] = header[0].lstrip("\ufeff")
        for row in rows[1:]:
            if len(row) != len(header):
                raise ValueError("wrong number of columns")
        return header, rows[1:]

    def solve_linear_system(A, b):
        n = len(A)
        M = [list(map(float, A[i])) + [float(b[i])] for i in range(n)]

        for col in range(n):
            pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
            if abs(M[pivot][col]) < 1e-12:
                raise ValueError("singular design matrix")

            if pivot != col:
                M[col], M[pivot] = M[pivot], M[col]

            divisor = M[col][col]
            for j in range(col, n + 1):
                M[col][j] /= divisor

            for r in range(n):
                if r == col:
                    continue
                factor = M[r][col]
                if factor != 0.0:
                    for j in range(col, n + 1):
                        M[r][j] -= factor * M[col][j]

        return [M[i][n] for i in range(n)]

    train_header, train_rows = read_csv(train_csv)
    test_header, test_rows = read_csv(test_csv)

    if target not in train_header:
        raise ValueError("target column not found")

    target_index = train_header.index(target)
    feature_indices = [i for i in range(len(train_header)) if i != target_index]
    feature_names = [train_header[i] for i in feature_indices]

    test_header_index = {name: i for i, name in enumerate(test_header)}
    for name in feature_names:
        if name not in test_header_index:
            raise ValueError("missing feature column in test data")

    test_feature_indices = [test_header_index[name] for name in feature_names]

    X = []
    y = []

    for row in train_rows:
        features = [parse_value(row[i]) for i in feature_indices]
        target_value = parse_value(row[target_index])
        X.append([1.0] + features)
        y.append(target_value)

    if not X:
        raise ValueError("no training data")

    p = len(X[0])
    XtX = [[0.0] * p for _ in range(p)]
    Xty = [0.0] * p

    for row, target_value in zip(X, y):
        for i in range(p):
            Xty[i] += row[i] * target_value
            for j in range(p):
                XtX[i][j] += row[i] * row[j]

    try:
        beta = solve_linear_system(XtX, Xty)
    except ValueError:
        ridge = 1e-10
        for i in range(p):
            XtX[i][i] += ridge
        beta = solve_linear_system(XtX, Xty)

    predictions = []

    for row in test_rows:
        features = [parse_value(row[i]) for i in test_feature_indices]
        prediction = beta[0]
        for j, feature in enumerate(features):
            prediction += beta[j + 1] * feature
        predictions.append(float(prediction))

    return predictions
```

