from html.parser import HTMLParser

class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found_table = False
        self.finished = False
        self.table_depth = 0
        self.rows = []
        self.current_row = None
        self.current_cell = None

    def handle_starttag(self, tag, attrs):
        if self.finished:
            return

        tag = tag.lower()

        if tag == "table":
            if not self.found_table:
                for name, value in attrs:
                    if name.lower() == "class" and value == "data-table":
                        self.found_table = True
                        self.table_depth = 1
                        break
            else:
                self.table_depth += 1

        elif self.found_table:
            if tag == "tr" and self.table_depth == 1:
                if self.current_cell is not None:
                    self._finish_cell()
                self.current_row = []
                self.rows.append(self.current_row)

            elif tag == "td" and self.table_depth == 1:
                if self.current_cell is not None:
                    self._finish_cell()
                if self.current_row is not None:
                    self.current_cell = []

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        self.handle_starttag(tag, attrs)
        if tag in ("table", "tr", "td"):
            self.handle_endtag(tag)

    def handle_endtag(self, tag):
        if self.finished:
            return

        tag = tag.lower()

        if not self.found_table:
            return

        if tag == "table":
            if self.table_depth > 0:
                self.table_depth -= 1

            if self.table_depth == 0:
                if self.current_cell is not None:
                    self._finish_cell()
                self.current_row = None
                self.finished = True

        elif tag == "tr" and self.table_depth == 1:
            if self.current_cell is not None:
                self._finish_cell()
            self.current_row = None

        elif tag == "td" and self.table_depth == 1:
            if self.current_cell is not None:
                self._finish_cell()

    def handle_data(self, data):
        if self.found_table and not self.finished and self.current_cell is not None:
            self.current_cell.append(data)

    def _finish_cell(self):
        if self.current_cell is not None and self.current_row is not None:
            self.current_row.append("".join(self.current_cell))
        self.current_cell = None

    def finish(self):
        if self.current_cell is not None:
            self._finish_cell()


def extract_data_table_rows(html):
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    parser.finish()
    return parser.rows
