from html.parser import HTMLParser

class _Node:
    __slots__ = ("tag", "attrs", "children")

    def __init__(self, tag, attrs=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []


class _TreeParser(HTMLParser):
    _VOID = {
        "area", "base", "br", "col", "embed", "hr", "img", "input",
        "link", "meta", "param", "source", "track", "wbr"
    }

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node(None)
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, dict(attrs))
        self.stack[-1].children.append(node)
        if tag not in self._VOID:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        node = _Node(tag, dict(attrs))
        self.stack[-1].children.append(node)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                break

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def _has_class(node, class_name):
    class_value = node.attrs.get("class") or ""
    return class_name in class_value.split()


def _iter_containers(node):
    if node.tag == "div" and _has_class(node, "container"):
        yield node

    for child in node.children:
        if isinstance(child, _Node):
            yield from _iter_containers(child)


def _find_first(node, predicate):
    for child in node.children:
        if isinstance(child, _Node):
            if predicate(child):
                return child
            found = _find_first(child, predicate)
            if found is not None:
                return found
    return None


def _get_text(node):
    parts = []

    def walk(current):
        for child in current.children:
            if isinstance(child, str):
                parts.append(child)
            else:
                walk(child)

    walk(node)
    return "".join(parts).strip()


def extract_article_info(html):
    parser = _TreeParser()
    parser.feed(html)
    parser.close()

    result = []

    for container in _iter_containers(parser.root):
        title_node = _find_first(container, lambda n: n.tag == "h1")
        date_node = _find_first(
            container,
            lambda n: n.tag == "span" and _has_class(n, "date")
        )
        author_node = _find_first(
            container,
            lambda n: n.tag == "span" and _has_class(n, "author")
        )

        title = _get_text(title_node) if title_node is not None else "No Title"
        date = _get_text(date_node) if date_node is not None else "No Date"
        author = _get_text(author_node) if author_node is not None else "No Author"

        result.append((title, date, author))

    return result
