def seasonal_decomposition(values, period, model):
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if period <= 0:
        raise ValueError("period must be positive")

    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    trend = [None] * n

    if period % 2 == 1:
        half = period // 2
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:
        half = period // 2
        for i in range(half, n - half):
            s = 0.5 * values[i - half] + 0.5 * values[i + half]
            s += sum(values[i - half + 1:i + half])
            trend[i] = s / period

    phase_sums = [0.0] * period
    phase_counts = [0] * period

    for i, t in enumerate(trend):
        if t is None:
            continue

        phase = i % period
        if model == "additive":
            phase_sums[phase] += values[i] - t
        else:
            phase_sums[phase] += values[i] / t
        phase_counts[phase] += 1

    raw_seasonal = [
        phase_sums[q] / phase_counts[q]
        for q in range(period)
    ]

    if model == "additive":
        mean = sum(raw_seasonal) / period
        seasonal_indices = [x - mean for x in raw_seasonal]
    else:
        mean = sum(raw_seasonal) / period
        seasonal_indices = [x / mean for x in raw_seasonal]

    seasonal = [seasonal_indices[i % period] for i in range(n)]

    residual = [None] * n
    for i, t in enumerate(trend):
        if t is None:
            continue

        if model == "additive":
            residual[i] = values[i] - t - seasonal[i]
        else:
            residual[i] = values[i] / (t * seasonal[i])

    return {
        "trend": trend,
        "seasonal": seasonal,
        "residual": residual,
    }
