```python
def column_linear_regression(rows, columns, target):
    if not rows:
        raise ValueError("rows must not be empty")

    try:
        target_idx = columns.index(target)
    except ValueError:
        raise ValueError("target must be one of the columns")

    predictor_indices = [
        i for i in range(len(columns)) if i != target_idx
    ]

    n_features = len(predictor_indices) + 1  # includes intercept

    xtx = [[0.0] * n_features for _ in range(n_features)]
    xty = [0.0] * n_features

    for row in rows:
        if len(row) != len(columns):
            raise ValueError("row length does not match number of columns")

        x = [1.0] + [float(row[i]) for i in predictor_indices]
        y = float(row[target_idx])

        for i in range(n_features):
            xty[i] += x[i] * y
            for j in range(n_features):
                xtx[i][j] += x[i] * x[j]

    beta = _solve_linear_system(xtx, xty)

    coefficients = beta[1:]
    intercept = beta[0]

    return coefficients, intercept


def _solve_linear_system(A, b):
    n = len(A)
    M = [list(map(float, A[i])) + [float(b[i])] for i in range(n)]

    pivot_columns = []
    row = 0

    for col in range(n):
        pivot = max(range(row, n), key=lambda r: abs(M[r][col]))

        if abs(M[pivot][col]) < 1e-12:
            continue

        M[row], M[pivot] = M[pivot], M[row]

        pivot_value = M[row][col]
        for j in range(col, n + 1):
            M[row][j] /= pivot_value

        for r in range(n):
            if r == row:
                continue

            factor = M[r][col]
            if abs(factor) < 1e-15:
                continue

            for j in range(col, n + 1):
                M[r][j] -= factor * M[row][j]

        pivot_columns.append(col)
        row += 1

        if row == n:
            break

    solution = [0.0] * n
    for i, col in enumerate(pivot_columns):
        solution[col] = M[i][n]

    return solution
