        'Temperature': 1,
        'Humidity': 2,
        'Wind Speed': 3,
        'Precipitation': 4
    }[column]

    values = [row[column_index] for row in data]

    if not values:
        return {
            'sum': 0,
            'mean': None,
            'min': None,
            'max': None,
            'histogram': [0] * 10
        }

    total = sum(values)
    mean = total / len(values)
    minimum = min(values)
    maximum = max(values)

    histogram = [0] * 10

    if minimum == maximum:
        histogram[9] = len(values)
    else:
        bin_width = (maximum - minimum) / 10.0

        for value in values:
            if value == maximum:
                index = 9
            else:
                index = int((value - minimum) / bin_width)
                index = max(0, min(index, 9))

            histogram[index] += 1

    return {
        'sum': total,
        'mean': mean,
        'min': minimum,
        'max': maximum,
        'histogram': histogram
    }
