from collections import defaultdict, Counter

def association_chi_square(left, right):
    left_by_id = defaultdict(list)
    for id_, category in left:
        left_by_id[id_].append(category)

    right_by_id = defaultdict(list)
    for id_, category in right:
        right_by_id[id_].append(category)

    table = defaultdict(Counter)
    row_categories = set()
    col_categories = set()
    total = 0

    # Join on id, creating all matching pairs.
    for id_ in set(left_by_id) & set(right_by_id):
        for left_cat in left_by_id[id_]:
            for right_cat in right_by_id[id_]:
                table[left_cat][right_cat] += 1
                row_categories.add(left_cat)
                col_categories.add(right_cat)
                total += 1

    if total == 0:
        return 0.0, 0

    row_totals = {row: sum(table[row].values()) for row in row_categories}
    col_totals = {
        col: sum(table[row][col] for row in row_categories)
        for col in col_categories
    }

    statistic = 0.0

    for row in row_categories:
        for col in col_categories:
            observed = table[row][col]
            expected = row_totals[row] * col_totals[col] / total

            if expected > 0:
                statistic += (observed - expected) ** 2 / expected

    dof = (len(row_categories) - 1) * (len(col_categories) - 1)

    return statistic, dof
