import math


def describe_filled_columns(columns):
    def percentile(sorted_values, q):
        if not sorted_values:
            return float("nan")
        if len(sorted_values) == 1:
            return float(sorted_values[0])

        pos = (len(sorted_values) - 1) * q
        lower = math.floor(pos)
        upper = math.ceil(pos)

        if lower == upper:
            return float(sorted_values[int(pos)])

        fraction = pos - lower
        return float(
            sorted_values[lower]
            + (sorted_values[upper] - sorted_values[lower]) * fraction
        )

    result = {}

    for name, values in columns.items():
        present = [v for v in values if v is not None]

        if present:
            fill_value = sum(present) / len(present)
            filled = [fill_value if v is None else v for v in values]
            numeric = [float(v) for v in filled]

            count = float(len(numeric))
            mean = sum(numeric) / len(numeric)

            if len(numeric) > 1:
                variance = sum((x - mean) ** 2 for x in numeric) / (len(numeric) - 1)
                std = math.sqrt(variance)
            else:
                std = float("nan")

            sorted_values = sorted(numeric)
            min_value = float(sorted_values[0])
            max_value = float(sorted_values[-1])
        else:
            count = 0.0
            mean = float("nan")
            std = float("nan")
            sorted_values = []
            min_value = float("nan")
            max_value = float("nan")

        result[name] = {
            "count": count,
            "mean": mean,
            "std": std,
            "min": min_value,
            "25%": percentile(sorted_values, 0.25),
            "50%": percentile(sorted_values, 0.50),
            "75%": percentile(sorted_values, 0.75),
            "max": max_value,
        }

    return result
