import math

def spectrum_magnitude_histogram(pairs):
    if not pairs:
        return ([], [])

    values = [value for _, value in pairs]
    n = len(values)

    magnitudes = []
    for k in range(n):
        real = 0.0
        imag = 0.0
        for t, value in enumerate(values):
            angle = -2.0 * math.pi * k * t / n
            real += value * math.cos(angle)
            imag += value * math.sin(angle)
        magnitudes.append(math.hypot(real, imag))

    lo = min(magnitudes)
    hi = max(magnitudes)
    counts = [0] * 10

    if hi == lo:
        counts[-1] = len(magnitudes)
        return (magnitudes, counts)

    width = (hi - lo) / 10.0

    for magnitude in magnitudes:
        if magnitude == hi:
            index = 9
        else:
            index = int((magnitude - lo) / width)
            index = max(0, min(index, 9))
        counts[index] += 1

    return (magnitudes, counts)
