def standardize_by_group(records):
    required = ("id", "age", "income")

    for record in records:
        if not isinstance(record, dict) or any(key not in record for key in required):
            raise ValueError("Each record must contain 'id', 'age', and 'income'")

    groups = {}
    for i, record in enumerate(records):
        groups.setdefault(record["id"], []).append(i)

    result = [None] * len(records)

    for indices in groups.values():
        n = len(indices)

        ages = [records[i]["age"] for i in indices]
        incomes = [records[i]["income"] for i in indices]

        mean_age = sum(ages) / n
        mean_income = sum(incomes) / n

        age_constant = all(value == ages[0] for value in ages)
        income_constant = all(value == incomes[0] for value in incomes)

        if age_constant:
            std_age = 0.0
        else:
            std_age = (sum((value - mean_age) ** 2 for value in ages) / n) ** 0.5

        if income_constant:
            std_income = 0.0
        else:
            std_income = (
                sum((value - mean_income) ** 2 for value in incomes) / n
            ) ** 0.5

        for i in indices:
            record = records[i]

            z_age = 0.0 if std_age == 0 else (record["age"] - mean_age) / std_age
            z_income = (
                0.0
                if std_income == 0
                else (record["income"] - mean_income) / std_income
            )

            result[i] = {
                "id": record["id"],
                "age": float(z_age),
                "income": float(z_income),
            }

    return result
