import xml.etree.ElementTree as ET

def xml_to_dict(xml):
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as e:
        raise ValueError(f"Malformed XML: {e}") from e

    def convert(elem):
        children = list(elem)

        # Collect direct text for this element, including text after child elements.
        text_parts = []
        if elem.text:
            text_parts.append(elem.text)

        child_groups = {}
        for child in children:
            tag = child.tag
            child_groups.setdefault(tag, []).append(convert(child))

            if child.tail:
                text_parts.append(child.tail)

        text = "".join(text_parts).strip()

        # Leaf element: no attributes and no children.
        if not elem.attrib and not children:
            return text if text else None

        result = {f"@{key}": value for key, value in elem.attrib.items()}

        for tag, values in child_groups.items():
            result[tag] = values[0] if len(values) == 1 else values

        if text:
            result["#text"] = text

        return result

    return {root.tag: convert(root)}
