import math

def standardized_tensor_product(P, T):
    if not P or not T:
        raise ValueError("P and T must be non-empty")

    k = len(P[0])
    if len(T) != k:
        raise ValueError("P's number of columns must match T's first dimension")

    n = len(T[0])
    if n == 0:
        return []

    p = len(T[0][0])

    table = []

    for j in range(n):
        flat_row = []

        for prow in P:
            for c in range(p):
                value = 0
                for i in range(k):
                    value += prow[i] * T[i][j][c]
                flat_row.append(float(value))

        table.append(flat_row)

    num_rows = len(table)
    if num_rows == 0:
        return table

    num_cols = len(table[0]) if table else 0

    for c in range(num_cols):
        first = table[0][c]
        same = True

        for r in range(1, num_rows):
            if table[r][c] != first:
                same = False
                break

        if same:
            for r in range(num_rows):
                table[r][c] = 0.0
            continue

        total = 0.0
        for r in range(num_rows):
            total += table[r][c]
        mean = total / num_rows

        variance_sum = 0.0
        for r in range(num_rows):
            diff = table[r][c] - mean
            variance_sum += diff * diff

        variance = variance_sum / num_rows

        if variance == 0.0:
            for r in range(num_rows):
                table[r][c] = 0.0
        else:
            std = math.sqrt(variance)
            for r in range(num_rows):
                table[r][c] = (table[r][c] - mean) / std

    return table
