import csv
from io import StringIO

def fill_missing_with_column_mean(csv_text):
    reader = csv.reader(StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        return {}

    if not header:
        return {}

    rows = list(reader)
    result = {}

    for i, column_name in enumerate(header):
        cells = [
            row[i] if i < len(row) else ""
            for row in rows
        ]

        present = [cell for cell in cells if cell != ""]

        # If the column has no present values, make every cell None.
        if not present:
            result[column_name] = [None for _ in cells]
            continue

        try:
            numbers = [float(cell) for cell in present]
        except ValueError:
            # Non-numeric column: empty strings become None.
            result[column_name] = [
                None if cell == "" else cell
                for cell in cells
            ]
        else:
            # Numeric column: fill empty cells with the mean.
            mean = sum(numbers) / len(numbers)
            result[column_name] = [
                mean if cell == "" else float(cell)
                for cell in cells
            ]

    return result
