import math

def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    result = {}

    for column, values in data.items():
        processed = []
        for value in values:
            try:
                processed.append(
                    replacements[value] if value in replacements else value
                )
            except TypeError:
                processed.append(value)

        if any(isinstance(value, str) for value in processed):
            distinct = sorted(set(processed))
            codes = {value: i for i, value in enumerate(distinct)}
            processed = [codes[value] for value in processed]

        n = len(processed)
        if n == 0:
            result[column] = []
            continue

        mean = sum(processed) / n

        if n == 1:
            result[column] = [0.0]
            continue

        variance = sum((value - mean) ** 2 for value in processed) / (n - 1)
        std = math.sqrt(variance)

        if std == 0:
            result[column] = [0.0 for _ in processed]
        else:
            result[column] = [(value - mean) / std for value in processed]

    return result
