import math
from numbers import Real

def correlation_without_column(data, column):
    columns = {}
    for name, values in data.items():
        if name == column:
            continue
        if all(isinstance(v, Real) and not isinstance(v, bool) for v in values):
            columns[name] = list(values)

    if not columns:
        return None

    names = list(columns)
    n = len(next(iter(columns.values())))

    if n == 0:
        return None

    means = {}
    centered = {}
    sums_sq = {}

    for name in names:
        vals = columns[name]
        mean = sum(vals) / n
        means[name] = mean
        centered[name] = [v - mean for v in vals]
        sums_sq[name] = sum(d * d for d in centered[name])

    result = {}

    for x in names:
        result[x] = {}
        for y in names:
            denominator = math.sqrt(sums_sq[x] * sums_sq[y])

            if denominator == 0:
                result[x][y] = 1.0 if x == y else 0.0
            else:
                covariance = sum(
                    a * b for a, b in zip(centered[x], centered[y])
                )
                result[x][y] = covariance / denominator

    return result
