def grade_report(students, subjects, grades):
    report = {}

    for i, student in enumerate(students):
        student_grades = {
            subject: float(grades[i][j])
            for j, subject in enumerate(subjects)
        }

        if subjects:
            average_grade = sum(student_grades.values()) / len(subjects)
        else:
            average_grade = 0.0

        student_grades["Average Grade"] = average_grade
        report[student] = student_grades

    averages = {}

    for j, subject in enumerate(subjects):
        if students:
            averages[subject] = sum(
                float(grades[i][j]) for i in range(len(students))
            ) / len(students)
        else:
            averages[subject] = 0.0

    if students:
        averages["Average Grade"] = sum(
            report[student]["Average Grade"] for student in students
        ) / len(students)
    else:
        averages["Average Grade"] = 0.0

    report["Average"] = averages
    return report
