import math

def zscores_by_date(rows):
    if not rows:
        return []

    n = len(rows)
    col_count = len(rows[0][1])

    means = [0.0] * col_count
    for _, values in rows:
        for j, x in enumerate(values):
            means[j] += x

    for j in range(col_count):
        means[j] /= n

    # Detect constant columns to avoid floating-point issues when std should be 0.
    constant = [True] * col_count
    first_values = rows[0][1]

    for _, values in rows[1:]:
        for j, x in enumerate(values):
            if x != first_values[j]:
                constant[j] = False

    stds = [0.0] * col_count
    for j in range(col_count):
        if not constant[j]:
            variance = sum((values[j] - means[j]) ** 2 for _, values in rows) / n
            stds[j] = math.sqrt(variance)

    result = []
    for date, values in rows:
        zscores = []
        for j, x in enumerate(values):
            if stds[j] == 0.0:
                zscores.append(0.0)
            else:
                zscores.append((x - means[j]) / stds[j])
        result.append([date] + zscores)

    return result
