import math

def _jacobi_eigh(A):
    n = len(A)
    G = [row[:] for row in A]
    V = [[0.0] * n for _ in range(n)]
    for i in range(n):
        V[i][i] = 1.0

    if n == 0:
        return [], V

    for _ in range(100):
        scale = max([abs(G[i][i]) for i in range(n)] + [1.0])
        tol = 1e-15 * scale
        off_max = 0.0

        for p in range(n - 1):
            for q in range(p + 1, n):
                Gpq = G[p][q]
                if abs(Gpq) <= tol:
                    continue

                off_max = max(off_max, abs(Gpq))
                Gpp = G[p][p]
                Gqq = G[q][q]

                theta = (Gqq - Gpp) / (2.0 * Gpq)
                if theta == 0.0:
                    t = 1.0
                else:
                    t = math.copysign(1.0, theta) / (
                        abs(theta) + math.sqrt(theta * theta + 1.0)
                    )

                c = 1.0 / math.sqrt(t * t + 1.0)
                s = t * c

                for k in range(n):
                    if k != p and k != q:
                        Gkp = G[k][p]
                        Gkq = G[k][q]
                        new_kp = c * Gkp - s * Gkq
                        new_kq = s * Gkp + c * Gkq
                        G[k][p] = new_kp
                        G[p][k] = new_kp
                        G[k][q] = new_kq
                        G[q][k] = new_kq

                G[p][p] = c * c * Gpp - 2.0 * s * c * Gpq + s * s * Gqq
                G[q][q] = s * s * Gpp + 2.0 * s * c * Gpq + c * c * Gqq
                G[p][q] = G[q][p] = 0.0

                for k in range(n):
                    Vkp = V[k][p]
                    Vkq = V[k][q]
                    V[k][p] = c * Vkp - s * Vkq
                    V[k][q] = s * Vkp + c * Vkq

        if off_max <= tol:
            break

    return [G[i][i] for i in range(n)], V


def fit_linear_regression(rows, targets):
    n = len(rows)
    if n == 0 or len(targets) != n:
        raise ValueError("rows must be non-empty and have the same length as targets")

    p = len(rows[0])
    for r in rows:
        if len(r) != p:
            raise ValueError("all rows must have the same length")

    if p == 0:
        mean_y = sum(float(t) for t in targets) / n
        return ([], mean_y)

    mean_x = [0.0] * p
    for r in rows:
        for j in range(p):
            mean_x[j] += float(r[j])
    for j in range(p):
        mean_x[j] /= n

    mean_y = sum(float(t) for t in targets) / n

    G = [[0.0] * p for _ in range(p)]
    c = [0.0] * p

    for r, y in zip(rows, targets):
        xc = [float(r[j]) - mean_x[j] for j in range(p)]
        yc = float(y) - mean_y

        for j in range(p):
            c[j] += xc[j] * yc
            for k in range(j, p):
                G[j][k] += xc[j] * xc[k]

    for j in range(p):
        for k in range(j + 1, p):
            G[k][j] = G[j][k]

    eigvals, V = _jacobi_eigh(G)
    max_eig = max(abs(v) for v in eigvals) if eigvals else 0.0
    tol = max_eig * 1e-12 if max_eig > 0 else 0.0

    beta = [0.0] * p
    for i in range(p):
        lam = eigvals[i]
        if lam > tol:
            v = [V[k][i] for k in range(p)]
            vt_c = sum(v[j] * c[j] for j in range(p))
            coeff = vt_c / lam
            for j in range(p):
                beta[j] += coeff * v[j]

    intercept = mean_y - sum(mean_x[j] * beta[j] for j in range(p))
    return (beta, float(intercept))
