import json
import math


def _linear_quantile(sorted_values, p):
    """Return the p-quantile using linear interpolation between points."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])

    position = (n - 1) * p
    lower = math.floor(position)
    upper = math.ceil(position)

    if lower == upper:
        return float(sorted_values[lower])

    fraction = position - lower
    return float(
        sorted_values[lower]
        + (sorted_values[upper] - sorted_values[lower]) * fraction
    )


def boxplot_stats_at_path(json_data, key_path):
    try:
        current = json.loads(json_data)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Malformed JSON") from exc

    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(key)
        current = current[key]

    if not isinstance(current, str):
        raise ValueError("Value at key path is not a comma-separated string")

    if current.strip() == "":
        raise ValueError("Data string is empty")

    values = []
    for token in current.split(","):
        token = token.strip()
        if token == "":
            raise ValueError("Data string contains an empty value")

        try:
            value = float(token)
        except ValueError as exc:
            raise ValueError(f"Non-numeric value: {token!r}") from exc

        if not math.isfinite(value):
            raise ValueError(f"Non-numeric value: {token!r}")

        values.append(value)

    values.sort()

    q1 = _linear_quantile(values, 0.25)
    median = _linear_quantile(values, 0.50)
    q3 = _linear_quantile(values, 0.75)
    iqr = q3 - q1

    lower_fence = q1 - 1.5 * iqr
    upper_fence = q3 + 1.5 * iqr

    inliers = [
        value
        for value in values
        if lower_fence <= value <= upper_fence
    ]

    outliers = [
        float(value)
        for value in values
        if value < lower_fence or value > upper_fence
    ]

    return {
        "q1": q1,
        "median": median,
        "q3": q3,
        "whisker_low": float(inliers[0]),
        "whisker_high": float(inliers[-1]),
        "outliers": outliers,
    }
