from html.parser import HTMLParser


class _TableParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)
        self.table_id = table_id
        self.table_depth = 0
        self.target_level = None
        self.found = False
        self.done = False
        self.rows = []
        self.current_row = None
        self.cell_chunks = None

    def _in_target_table(self):
        return (
            self.found
            and not self.done
            and self.target_level is not None
            and self.table_depth == self.target_level
        )

    def _finish_cell(self):
        if self.cell_chunks is not None:
            text = "".join(self.cell_chunks).strip()
            if self.current_row is None:
                self.current_row = []
            self.current_row.append(text)
            self.cell_chunks = None

    def _finish_row(self):
        if self.current_row is not None:
            self.rows.append(self.current_row)
            self.current_row = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        tag = tag.lower()

        if tag == "table":
            self.table_depth += 1
            if not self.found:
                attrs_dict = {name.lower(): value for name, value in attrs}
                if attrs_dict.get("id") == self.table_id:
                    self.found = True
                    self.target_level = self.table_depth
            return

        if self._in_target_table():
            if tag == "tr":
                self._finish_cell()
                self._finish_row()
                self.current_row = []
            elif tag in ("td", "th"):
                if self.current_row is None:
                    self.current_row = []
                self._finish_cell()
                self.cell_chunks = []

    def handle_endtag(self, tag):
        if self.done:
            return

        tag = tag.lower()

        if tag == "table":
            if self.found and self.table_depth == self.target_level:
                self._finish_cell()
                self._finish_row()
                self.done = True

            if self.table_depth > 0:
                self.table_depth -= 1
            return

        if self._in_target_table():
            if tag in ("td", "th"):
                self._finish_cell()
            elif tag == "tr":
                self._finish_cell()
                self._finish_row()

    def handle_data(self, data):
        if self.done:
            return
        if self.cell_chunks is not None:
            self.cell_chunks.append(data)


def html_table_records(html, table_id):
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r}")

    rows = parser.rows
    if not rows:
        return []

    headers = rows[0]
    return [dict(zip(headers, row)) for row in rows[1:]]
