import math

def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = list(data.keys())
    mapped_data = {
        col: [mapping.get(value, value) for value in data[col]]
        for col in columns
    }

    result = {a: {} for a in columns}

    for a in columns:
        x = mapped_data[a]
        for b in columns:
            if a == b:
                result[a][b] = 1.0
                continue

            y = mapped_data[b]
            n = len(x)

            if n == 0:
                result[a][b] = 0.0
                continue

            mean_x = sum(x) / n
            mean_y = sum(y) / n

            covariance = sum(
                (xi - mean_x) * (yi - mean_y)
                for xi, yi in zip(x, y)
            )
            variance_x = sum((xi - mean_x) ** 2 for xi in x)
            variance_y = sum((yi - mean_y) ** 2 for yi in y)

            denominator = math.sqrt(variance_x * variance_y)
            result[a][b] = covariance / denominator if denominator else 0.0

    return result
