```python
from datetime import date, datetime
import calendar
import re

_WEEKDAYS = {
    "MON": 0,
    "TUE": 1,
    "WED": 2,
    "THU": 3,
    "FRI": 4,
    "SAT": 5,
    "SUN": 6,
}

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}")


def _add_months(year, month, delta):
    idx = year * 12 + (month - 1) + delta
    return idx // 12, idx % 12 + 1


def _month_end_date(year, month):
    return date(year, month, calendar.monthrange(year, month)[1])


def _nth_weekday_date(year, month, n, weekday):
    first = date(year, month, 1)
    offset = (weekday - first.weekday()) % 7
    return date(year, month, 1 + offset + 7 * (n - 1))


def _month_end_dates(start):
    year, month = start.year, start.month
    current = _month_end_date(year, month)

    if current < start:
        year, month = _add_months(year, month, 1)
        current = _month_end_date(year, month)

    while True:
        yield current
        year, month = _add_months(year, month, 1)
        current = _month_end_date(year, month)


def _quarter_end_dates(start):
    year, month = start.year, start.month

    while True:
        if month in (3, 6, 9, 12):
            current = _month_end_date(year, month)
            if current >= start:
                break
        year, month = _add_months(year, month, 1)

    while True:
        yield _month_end_date(year, month)
        year, month = _add_months(year, month, 3)


def _nth_weekday_dates(start, n, weekday):
    year, month = start.year, start.month
    current = _nth_weekday_date(year, month, n, weekday)

    if current < start:
        year, month = _add_months(year, month, 1)
        current = _nth_weekday_date(year, month, n, weekday)

    while True:
        yield current
        year, month = _add_months(year, month, 1)
        current = _nth_weekday_date(year, month, n, weekday)


def forecast_schedule(start_date, freq, sales):
    if not isinstance(start_date, str) or _DATE_RE.fullmatch(start_date) is None:
        raise ValueError("Invalid start date")

    try:
        start = datetime.strptime(start_date, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("Invalid start date") from None

    if freq == "month-end":
        dates = _month_end_dates(start)

    elif freq == "quarter-end":
        dates = _quarter_end_dates(start)

    elif isinstance(freq, str):
        parts = freq.split("-")
        if len(parts) != 2:
            raise ValueError("Invalid frequency")

        try:
            n = int(parts[0])
        except ValueError:
            raise ValueError("Invalid frequency") from None

        weekday_name = parts[1].upper()

        if not (1 <= n <= 4) or weekday_name not in _WEEKDAYS:
            raise ValueError("Invalid frequency")

        dates = _nth_weekday_dates(start, n, _WEEKDAYS[weekday_name])

    else:
        raise ValueError("Invalid frequency")

    result = []
    for sale in sales:
        result.append((next(dates).isoformat(), sale))

    return result
