import csv
import io
from collections import Counter

def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.DictReader(io.StringIO(csv_text, newline=""))

    required = {"Customer", "Category", "Sales"}
    if reader.fieldnames is None or not required.issubset(reader.fieldnames):
        raise ValueError("CSV must contain Customer, Category, and Sales columns")

    seen_customers = set()
    total_sales = 0
    categories = []

    for row in reader:
        customer = row["Customer"]

        if customer in seen_customers:
            continue

        seen_customers.add(customer)
        categories.append(row["Category"])

        sales = row["Sales"].strip()
        try:
            sales_value = int(sales)
        except ValueError:
            sales_value = float(sales)

        total_sales += sales_value

    if categories:
        counts = Counter(categories)
        most_popular = min(counts.items(), key=lambda item: (-item[1], item[0]))[0]
    else:
        most_popular = None

    return {
        "Total Sales": total_sales,
        "Most Popular Category": most_popular,
    }
