from numbers import Real


def column_covariance(columns):
    if not columns:
        raise ValueError("table must contain at least one column")

    names = list(columns)
    data = []
    n_rows = None

    for name in names:
        values = list(columns[name])

        if n_rows is None:
            n_rows = len(values)
        elif len(values) != n_rows:
            raise ValueError("all columns must have the same length")

        for value in values:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise TypeError(f"column {name!r} contains a non-numeric value")

        data.append(values)

    if n_rows == 0:
        raise ValueError("table must contain at least one row")
    if n_rows < 2:
        raise ValueError("table must contain at least two rows")

    means = [sum(values) / n_rows for values in data]

    result = {}
    for i, a in enumerate(names):
        result[a] = {}
        for j, b in enumerate(names):
            covariance = sum(
                (data[i][k] - means[i]) * (data[j][k] - means[j])
                for k in range(n_rows)
            ) / (n_rows - 1)
            result[a][b] = covariance

    return result
