    records.sort(key=lambda record: (record[0], record[1]))

    score_sums = {}
    score_counts = {}

    for name, score in zip(names, scores):
        score_sums[name] = score_sums.get(name, 0) + score
        score_counts[name] = score_counts.get(name, 0) + 1

    averages = {
        name: score_sums[name] / score_counts[name]
        for name in sorted(score_sums)
    }

    if not ages:
        most_common_age = None
    else:
        age_counts = {}
        for age in ages:
            age_counts[age] = age_counts.get(age, 0) + 1
        most_common_age = max(age_counts, key=age_counts.get)

    return records, averages, most_common_age
