def complete_row_histogram(data, bins):
    columns = list(data.keys())

    if not columns:
        return {}, None

    row_count = len(data[columns[0]])
    cleaned = {col: [] for col in columns}
    pooled = []

    for i in range(row_count):
        row = [data[col][i] for col in columns]

        if any(value is None for value in row):
            continue

        for col, value in zip(columns, row):
            value = float(value)
            cleaned[col].append(value)
            pooled.append(value)

    if not pooled:
        return cleaned, None

    minimum = min(pooled)
    maximum = max(pooled)

    if minimum == maximum:
        return cleaned, None

    width = (maximum - minimum) / bins
    counts = [0] * bins

    for value in pooled:
        if value == maximum:
            index = bins - 1
        else:
            index = int((value - minimum) / width)
            index = max(0, min(index, bins - 1))

        counts[index] += 1

    return cleaned, counts
