import csv
import io
import math

def correlation_matrix_from_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        return {}

    rows = []
    for row in reader:
        if not row:
            continue
        rows.append([float(value) for value in row])

    n_rows = len(rows)
    n_cols = len(header)

    columns = [[rows[r][c] for r in range(n_rows)] for c in range(n_cols)]
    means = [sum(col) / n_rows for col in columns]

    # cov[i][j] stores the sum of products of deviations,
    # i.e. the unnormalized covariance.
    cov = [[0.0] * n_cols for _ in range(n_cols)]

    for i in range(n_cols):
        for j in range(i, n_cols):
            total = 0.0
            for r in range(n_rows):
                total += (columns[i][r] - means[i]) * (columns[j][r] - means[j])
            cov[i][j] = cov[j][i] = total

    result = {}

    for i, name_i in enumerate(header):
        result[name_i] = {}
        for j, name_j in enumerate(header):
            denominator = math.sqrt(cov[i][i] * cov[j][j])
            if denominator == 0:
                result[name_i][name_j] = float("nan")
            else:
                result[name_i][name_j] = cov[i][j] / denominator

    return result
