def fit_joined_regression(feature_rows, target_rows, features, target):
    target_by_id = {row['id']: row for row in target_rows}

    joined = []
    for frow in feature_rows:
        tid = frow['id']
        if tid in target_by_id:
            joined.append((frow, target_by_id[tid]))

    n = len(joined)
    k = len(features)

    if n == 0:
        return {
            'coefficients': [0.0] * k,
            'intercept': 0.0,
            'residuals': []
        }

    X = [[float(frow[f]) for f in features] for frow, _ in joined]
    y = [float(trow[target]) for _, trow in joined]

    y_mean = sum(y) / n

    if k == 0:
        intercept = y_mean
        residuals = [yi - intercept for yi in y]
        return {
            'coefficients': [],
            'intercept': float(intercept),
            'residuals': [float(r) for r in residuals]
        }

    x_means = [
        sum(X[i][j] for i in range(n)) / n
        for j in range(k)
    ]

    Xc = [
        [X[i][j] - x_means[j] for j in range(k)]
        for i in range(n)
    ]
    yc = [y[i] - y_mean for i in range(n)]

    # Normal equations: (Xc^T Xc) beta = Xc^T yc
    A = [[0.0] * k for _ in range(k)]
    b = [0.0] * k

    for i in range(n):
        for j in range(k):
            xij = Xc[i][j]
            b[j] += xij * yc[i]
            for l in range(k):
                A[j][l] += xij * Xc[i][l]

    beta = _solve_linear_system(A, b)

    intercept = y_mean - sum(beta[j] * x_means[j] for j in range(k))

    residuals = []
    for i in range(n):
        prediction = intercept
        for j in range(k):
            prediction += beta[j] * X[i][j]
        residuals.append(y[i] - prediction)

    return {
        'coefficients': [float(v) for v in beta],
        'intercept': float(intercept),
        'residuals': [float(r) for r in residuals]
    }


def _solve_linear_system(A, b):
    n = len(A)
    if n == 0:
        return []

    M = [list(map(float, A[i])) + [float(b[i])] for i in range(n)]
    eps = 1e-12

    row = 0
    pivot_cols = []

    for col in range(n):
        pivot = None
        max_abs = eps

        for r in range(row, n):
            val = abs(M[r][col])
            if val > max_abs:
                max_abs = val
                pivot = r

        if pivot is None:
            continue

        M[row], M[pivot] = M[pivot], M[row]

        pivot_value = M[row][col]
        for j in range(col, n + 1):
            M[row][j] /= pivot_value

        for r in range(n):
            if r == row:
                continue
            factor = M[r][col]
            if abs(factor) > eps:
                for j in range(col, n + 1):
                    M[r][j] -= factor * M[row][j]

        pivot_cols.append(col)
        row += 1

        if row == n:
            break

    solution = [0.0] * n
    for i, col in enumerate(pivot_cols):
        solution[col] = M[i][n]

    return solution
```

