def fruit_sales_box_stats(records):
    if not records:
        raise ValueError("records must not be empty")

    sales_by_fruit = {}

    for fruit, day, sales in records:
        sales_by_fruit.setdefault(fruit, []).append(float(sales))

    def percentile(sorted_values, p):
        if len(sorted_values) == 1:
            return sorted_values[0]

        position = (len(sorted_values) - 1) * p
        lower = int(position)
        upper = min(lower + 1, len(sorted_values) - 1)
        fraction = position - lower

        return sorted_values[lower] + fraction * (
            sorted_values[upper] - sorted_values[lower]
        )

    result = {}

    for fruit, sales in sales_by_fruit.items():
        sales.sort()

        minimum = sales[0]
        maximum = sales[-1]

        if len(sales) == 1:
            q1 = median = q3 = sales[0]
        else:
            q1 = percentile(sales, 0.25)
            median = percentile(sales, 0.50)
            q3 = percentile(sales, 0.75)

        result[fruit] = (minimum, q1, median, q3, maximum)

    return result
```

