from collections import Counter

def column_summary_stats(table, mapping, features):
    def replace(value):
        try:
            return mapping[value]
        except (KeyError, TypeError):
            return value

    result = {}

    for feature in features:
        if feature not in table:
            raise ValueError(f"Feature {feature!r} is not in table")

        values = [replace(v) for v in table[feature]]
        n = len(values)

        mean = sum(values) / n

        ordered = sorted(values)
        mid = n // 2
        if n % 2:
            median = float(ordered[mid])
        else:
            median = (ordered[mid - 1] + ordered[mid]) / 2.0

        counts = Counter(values)
        max_count = max(counts.values())
        mode = min(value for value, count in counts.items() if count == max_count)

        variance = sum((value - mean) ** 2 for value in values) / n

        result[feature] = {
            'mean': mean,
            'median': median,
            'mode': mode,
            'variance': variance,
        }

    return result
