from math import sqrt

def standardize_columns(rows, scale_cols):
    if not rows:
        return []

    n = len(rows)
    result = [list(row) for row in rows]

    for col in set(scale_cols):
        values = [row[col] for row in rows]
        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = sqrt(variance)

        if std == 0:
            for row in result:
                row[col] = 0.0
        else:
            for i, row in enumerate(result):
                row[col] = (rows[i][col] - mean) / std

    return result
