```python
from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found = False
        self.complete = False
        self.table_depth = 0
        self.headers = []
        self.rows = []
        self.current_row = None
        self.current_cell = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if tag == "table":
            if not self.found:
                self.found = True
                self.table_depth = 1
            elif self.table_depth >= 1:
                self.table_depth += 1
            return

        if not self.found or self.complete or self.table_depth != 1:
            return

        if tag == "tr":
            self._finalize_cell()
            self._finalize_row()
            self.current_row = []
        elif tag in ("th", "td"):
            self._finalize_cell()
            self.current_cell = {"tag": tag, "parts": []}

    def handle_endtag(self, tag):
        tag = tag.lower()

        if tag == "table":
            if not self.found or self.complete:
                return

            if self.table_depth == 1:
                self._finalize_cell()
                self._finalize_row()
                self.table_depth = 0
                self.complete = True
            elif self.table_depth > 1:
                self.table_depth -= 1
            return

        if not self.found or self.complete or self.table_depth != 1:
            return

        if tag in ("td", "th"):
            self._finalize_cell()
        elif tag == "tr":
            self._finalize_cell()
            self._finalize_row()

    def handle_data(self, data):
        if (
            self.found
            and not self.complete
            and self.table_depth >= 1
            and self.current_cell is not None
        ):
            self.current_cell["parts"].append(data)

    def _finalize_cell(self):
        if self.current_cell is None:
            return

        text = "".join(self.current_cell["parts"]).strip()

        if self.current_cell["tag"] == "th":
            self.headers.append(text)
        elif self.current_row is not None:
            self.current_row.append(text)

        self.current_cell = None

    def _finalize_row(self):
        if self.current_row is not None:
            if self.current_row:
                self.rows.append(self.current_row)
            self.current_row = None

    def finish(self):
        if self.found and not self.complete:
            self._finalize_cell()
            self._finalize_row()
            self.complete = True


def extract_first_table(html):
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()
    parser.finish()

    if not parser.found:
        raise ValueError("No table found")
    if not parser.rows:
        raise ValueError("No data rows found")

    return parser.headers, parser.rows
```

