import math

def row_zscores_and_correlation(data):
    if not data:
        return [], []

    z_scores = []

    for row in data:
        n = len(row)
        if n == 0:
            z_scores.append([])
            continue

        mean = sum(row) / n
        variance = sum((x - mean) ** 2 for x in row) / n
        std = math.sqrt(variance)

        if std == 0:
            z_scores.append([0.0] * n)
        else:
            z_scores.append([(x - mean) / std for x in row])

    n_rows = len(z_scores)
    n_cols = len(z_scores[0]) if n_rows else 0

    if n_cols == 0:
        return z_scores, []

    col_means = [
        sum(z_scores[r][c] for r in range(n_rows)) / n_rows
        for c in range(n_cols)
    ]

    col_stds = []
    for c in range(n_cols):
        mean = col_means[c]
        variance = sum((z_scores[r][c] - mean) ** 2 for r in range(n_rows))
        col_stds.append(math.sqrt(variance))

    corr = []

    for i in range(n_cols):
        corr_row = []
        for j in range(n_cols):
            if i == j:
                corr_row.append(1.0)
            elif col_stds[i] == 0 or col_stds[j] == 0:
                corr_row.append(0.0)
            else:
                covariance = sum(
                    (z_scores[r][i] - col_means[i]) *
                    (z_scores[r][j] - col_means[j])
                    for r in range(n_rows)
                )
                corr_row.append(covariance / (col_stds[i] * col_stds[j]))
        corr.append(corr_row)

    return z_scores, corr
```

