def integer_histogram_counts(data_str, separator=',', bins=20):
    if bins <= 0:
        raise ValueError("bins must be positive")
    if data_str.strip() == "":
        raise ValueError("empty input string")

    values = []
    for token in data_str.split(separator):
        token = token.strip()
        if token == "":
            raise ValueError("empty value")

        try:
            value = int(token)
        except ValueError:
            try:
                value = int(float(token))
            except (ValueError, OverflowError):
                raise ValueError(f"invalid numeric value: {token!r}")

        values.append(value)

    min_val = min(values)
    max_val = max(values)
    counts = [0] * bins

    if min_val == max_val:
        counts[-1] = len(values)
        return values, counts

    span = max_val - min_val

    for value in values:
        if value == max_val:
            index = bins - 1
        else:
            index = ((value - min_val) * bins) // span

        counts[index] += 1

    return values, counts
