import fnmatch
import re


def _natural_key(name):
    parts = re.split(r'([0-9]+)', name)
    return tuple(
        (1, int(part)) if part.isdigit() else (0, part.casefold())
        for part in parts
    )


def extract_matches_from_files(files, name_pattern, value_pattern):
    selected = [
        filename
        for filename in files
        if fnmatch.fnmatch(filename, name_pattern)
    ]

    if not selected:
        raise ValueError(f"No file names match pattern: {name_pattern!r}")

    selected.sort(key=_natural_key)

    regex = re.compile(value_pattern)
    result = []

    for filename in selected:
        matches = [
            match.group(0)
            for match in regex.finditer(files[filename])
        ]
        result.append((filename, matches))

    return result
