from bisect import bisect_right

def attribute_histogram(records, key, num_bins=30):
    if num_bins <= 0:
        raise ValueError("num_bins must be positive")

    values = [float(record[key]) for record in records]
    if not values:
        raise ValueError("records must contain at least one value")

    lo, hi = min(values), max(values)

    # Expand a zero-width range so equal-width bins have positive width.
    if lo == hi:
        lo -= 0.5
        hi += 0.5

    width = (hi - lo) / num_bins
    edges = [float(lo + i * width) for i in range(num_bins)]
    edges.append(float(hi))

    counts = [0] * num_bins

    for value in values:
        if value >= hi:
            idx = num_bins - 1
        else:
            idx = bisect_right(edges, value) - 1
            if idx < 0:
                idx = 0
            elif idx >= num_bins:
                idx = num_bins - 1
        counts[idx] += 1

    return counts, edges
