from io import StringIO
import csv
import math

def summarize_numeric_csv(csv_text):
    reader = csv.reader(StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        return {"means": {}, "std_devs": {}, "f_value": None}

    rows = [row for row in reader if any(cell.strip() for cell in row)]

    numeric_groups = {}
    for idx, name in enumerate(header):
        values = []
        valid = True

        for row in rows:
            if idx >= len(row):
                valid = False
                break

            cell = row[idx].strip()
            if not cell:
                valid = False
                break

            try:
                value = float(cell.replace(",", ""))
            except ValueError:
                valid = False
                break

            if not math.isfinite(value):
                valid = False
                break

            values.append(value)

        if valid and values:
            numeric_groups[name] = values

    means = {}
    std_devs = {}

    for name, values in numeric_groups.items():
        n = len(values)
        mean = sum(values) / n
        means[name] = mean

        if n > 1:
            variance = sum((x - mean) ** 2 for x in values) / (n - 1)
            std_devs[name] = math.sqrt(variance)
        else:
            std_devs[name] = 0.0

    if len(numeric_groups) < 2:
        f_value = None
    else:
        groups = list(numeric_groups.values())
        k = len(groups)
        total_n = sum(len(group) for group in groups)
        grand_mean = sum(sum(group) for group in groups) / total_n

        ss_between = 0.0
        ss_within = 0.0

        for group in groups:
            group_mean = sum(group) / len(group)
            ss_between += len(group) * (group_mean - grand_mean) ** 2
            ss_within += sum((x - group_mean) ** 2 for x in group)

        df_between = k - 1
        df_within = total_n - k

        if df_within <= 0:
            f_value = None
        else:
            ms_between = ss_between / df_between
            ms_within = ss_within / df_within

            if ms_within == 0:
                f_value = 0.0 if ms_between == 0 else float("inf")
            else:
                f_value = ms_between / ms_within

    return {
        "means": means,
        "std_devs": std_devs,
        "f_value": f_value,
    }
