import math

def max_pairwise_distance(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if n < 2:
        return 0.0

    max_sq_distance = 0.0

    for i in range(n):
        for j in range(i + 1, n):
            dx = xs[i] - xs[j]
            dy = ys[i] - ys[j]
            sq_distance = dx * dx + dy * dy
            if sq_distance > max_sq_distance:
                max_sq_distance = sq_distance

    return math.sqrt(max_sq_distance)
