import math

def standardize_columns(data):
    result = {}

    for name, values in data.items():
        n = len(values)

        if n == 0:
            result[name] = ([], [0] * 20)
            continue

        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = math.sqrt(variance)

        if std == 0:
            standardized = [0.0] * n
        else:
            standardized = [(x - mean) / std for x in values]

        counts = [0] * 20
        lo = min(standardized)
        hi = max(standardized)

        if hi == lo:
            counts[-1] = n
        else:
            width = (hi - lo) / 20.0

            for value in standardized:
                if value == hi:
                    index = 19
                else:
                    index = int((value - lo) / width)
                    index = max(0, min(index, 19))

                counts[index] += 1

        result[name] = (standardized, counts)

    return result
