def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    n = len(next(iter(table.values())))
    if n == 0:
        raise ValueError("table is empty")

    if any(len(values) != n for values in table.values()):
        raise ValueError("all columns must have the same length")

    def is_numeric_column(values):
        return all(
            isinstance(v, (int, float)) and not isinstance(v, bool)
            for v in values
        )

    numeric_cols = []
    numeric_stats = {}
    standardized = {}

    for col, values in table.items():
        if is_numeric_column(values):
            if all(v == values[0] for v in values):
                mean = values[0]
                std = 0.0
            else:
                mean = sum(values) / n
                variance = sum((v - mean) ** 2 for v in values) / n
                std = variance ** 0.5

            numeric_cols.append(col)
            numeric_stats[col] = (mean, std, values)

            if std == 0.0:
                standardized[col] = [0.0 for _ in values]
            else:
                standardized[col] = [(v - mean) / std for v in values]
        else:
            standardized[col] = list(values)

    if not numeric_cols:
        raise ValueError("table has no numeric columns")

    corr = []
    for i, a in enumerate(numeric_cols):
        mean_a, std_a, vals_a = numeric_stats[a]
        row = []

        for j, b in enumerate(numeric_cols):
            if i == j:
                row.append(1.0)
            else:
                mean_b, std_b, vals_b = numeric_stats[b]

                if std_a == 0.0 or std_b == 0.0:
                    row.append(0.0)
                else:
                    covariance = sum(
                        (x - mean_a) * (y - mean_b)
                        for x, y in zip(vals_a, vals_b)
                    ) / n
                    row.append(covariance / (std_a * std_b))

        corr.append(row)

    return standardized, corr
