from html.parser import HTMLParser

class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self._row_stack = []
        self._open_cells = []  # (row_reference, text_chunks)

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if tag == "tr":
            row = []
            self.rows.append(row)
            self._row_stack.append(row)

        elif tag == "td" and self._row_stack:
            self._open_cells.append((self._row_stack[-1], []))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        tag = tag.lower()

        if tag == "td":
            if self._open_cells:
                self._finish_cell()

        elif tag == "tr" and self._row_stack:
            row = self._row_stack[-1]
            while self._open_cells and self._open_cells[-1][0] is row:
                self._finish_cell()
            self._row_stack.pop()

    def handle_data(self, data):
        for _, chunks in self._open_cells:
            chunks.append(data)

    def _finish_cell(self):
        row, chunks = self._open_cells.pop()
        row.append("".join(chunks).strip())

    def finish(self):
        while self._open_cells:
            self._finish_cell()
        return self.rows


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()
    return parser.finish()
